PLACEHOLDER = re.compile(r"\{([A-Za-z0-9_]+)\}")


def placeholders(value: str) -> list[str]:
    return sorted(PLACEHOLDER.findall(value))


def main() -> None:
    en = json.loads((ROOT / "en.json").read_text(encoding="utf-8"))["spoolman"]
    for language, translations in (("ru", RU), ("uk", UK)):
        missing = sorted(set(en) - set(translations))
        extra = sorted(set(translations) - set(en))
        if missing or extra:
            raise SystemExit(f"{language}: Spoolman key mismatch; missing={missing}, extra={extra}")
        for key, source in en.items():
            if placeholders(source) != placeholders(translations[key]):
                raise SystemExit(f"{language}: placeholder mismatch for spoolman.{key}")
        path = ROOT / f"{language}.json"
        document = json.loads(path.read_text(encoding="utf-8"))
        document["spoolman"] = translations
        path.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(f"updated {language}: {len(translations)} Spoolman keys")


if __name__ == "__main__":
    main()
